import{_ as e,o,c as a,a2 as i}from"./chunks/framework.eFe5Lsvn.js";const b=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"app/troubleshooting.md","filePath":"app/troubleshooting.md"}'),r={name:"app/troubleshooting.md"};function n(s,t,l,d,h,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>When generation fails, the app lists what&#39;s wrong and pins the spot on the field. Click an issue to jump to it. These are the common ones.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;Waypoint N&#39;s bumpers overlap …&quot;</td><td>The robot at that pose hits an obstacle. Move or rotate it, or add a position tolerance.</td></tr><tr><td>&quot;Waypoint N&#39;s extended intake overlaps …&quot;</td><td>The intake is out at that waypoint and hits something. Rotate the waypoint, move it, or end the intake range earlier.</td></tr><tr><td>A heading or point-at is infeasible</td><td>Loosen the heading tolerance, make the heading free, or add distance or time between waypoints.</td></tr><tr><td>The path goes around the wrong side of an obstacle</td><td>Add a <strong>guide</strong> point on the side you want and drag it into place in the waypoint list.</td></tr><tr><td>Slow to generate</td><td>Use fewer waypoints, a larger sample spacing (Settings → Path solver), or fewer route candidates.</td></tr><tr><td>A &quot;Likely unsolvable&quot; panel appears while generating</td><td>The solver found a probable conflict early. Click an issue to inspect it, or <strong>Stop</strong> to end generation and keep the diagnosis.</td></tr></tbody></table><h2 id="simple-input-errors" tabindex="-1">Simple input errors <a class="header-anchor" href="#simple-input-errors" aria-label="Permalink to &quot;Simple input errors&quot;">​</a></h2><p>Some mistakes are caught before any optimization runs, with the exact waypoint index:</p><ul><li>missing waypoints</li><li>fixed poses outside the field or overlapping an obstacle</li><li>fixed headings that can&#39;t satisfy a point-at target</li><li>a straight line through an obstacle, or a fixed waypoint off the straight line</li><li>a fixed waypoint enclosed by obstacles</li></ul><h2 id="a-failed-solve-is-not-deployable" tabindex="-1">A failed solve is not deployable <a class="header-anchor" href="#a-failed-solve-is-not-deployable" aria-label="Permalink to &quot;A failed solve is not deployable&quot;">​</a></h2><p>A failed solve is not deployment-ready. Edit the path or constraint and generate again. For why the solver behaves this way, see <a href="/Mayhem/reference/solver">How the solver works</a>.</p><h2 id="on-the-robot" tabindex="-1">On the robot <a class="header-anchor" href="#on-the-robot" aria-label="Permalink to &quot;On the robot&quot;">​</a></h2><p>For problems when running paths (wrong place, mirrored on red, markers not firing), see <a href="/Mayhem/lib/troubleshooting">MayhemLib troubleshooting</a>.</p>',10)])])}const g=e(r,[["render",n]]);export{b as __pageData,g as default};
